require_once dirname(__DIR__, 3) . '/bootstrap.php'; $allowedRoles=[ROLE_HOUSE_MASTER,ROLE_HOUSE_MISTRESS]; require APP_ROOT.'/app/middleware/RoleMiddleware.php'; use App\Services\VisitorService; use App\Services\StudentService;
$houseId=current_user()['houseId']??null;$visitors=(new VisitorService())->byHouse($houseId);$students=StudentService::all($houseId);$studentMap=[];foreach($students as $student)$studentMap[(string)($student['id']??'')]=$student;$counts=[];foreach($visitors as $visitor){$status=(string)($visitor['status']??'unknown');$counts[$status]=($counts[$status]??0)+1;}$pageTitle='Visitor Report';$navItems=[['icon'=>'bi-file-earmark-text','label'=>'Reports','href'=>url('views/house-master/reports/index.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="d-flex justify-content-between mb-3"><div><h5 class="mb-1">Visitor Activity Report</h5><p class="text-muted mb-0">Visitor records and current status for your house.</p></div><a class="btn btn-outline-primary btn-sm" href="<?=url('views/house-master/visitors/index.php')?>">Open visitor log</a></div><div class="row g-3 mb-3"><?php foreach($counts as $status=>$count):?><div class="col-md-3"><div class="card stat-card p-3"><small class="text-muted"><?=e(ucwords(str_replace('_',' ',$status)))?></small><strong class="fs-2"><?=e((string)$count)?></strong></div></div><?php endforeach;?></div><div class="card stat-card p-3"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Visitor</th><th>Student</th><th>Purpose</th><th>Status</th><th>Visit date</th></tr></thead><tbody><?php foreach($visitors as $visitor):$student=$studentMap[(string)($visitor['studentId']??'')]??[];?><tr><td><?=e($visitor['visitorName']??'-')?></td><td><?=e(trim(($student['firstName']??'').' '.($student['lastName']??''))?:($visitor['studentId']??'-'))?></td><td><?=e($visitor['purpose']??'-')?></td><td><?=e($visitor['status']??'-')?></td><td><?=e($visitor['visitDate']??substr((string)($visitor['createdAt']??''),0,10))?></td></tr><?php endforeach;?><?php if(!$visitors):?><tr><td colspan="5" class="text-center text-muted">No visitor records found.</td></tr><?php endif;?></tbody></table></div></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>